function status(p) {
  if (p.stock<=0) return { label: 'Sin stock', tone: 'critical' };
  if (p.target > 0 && p.stock <= p.target * .1) return { label: 'Crítico', tone: 'critical' };
  if (p.target > 0 && p.stock <= p.target * .2) return { label: 'Bajo', tone: 'low' };
  return { label: 'Disponible', tone: 'available' };
}
