  const route = event.state.route;state.workspaceFocusId=route.workspaceFocusId;state.workspaceSearch=route.workspaceSearch||'';
  history = event.state.trail || [];
  Object.assign(state, {page:route.page,search:route.search || '',category:route.category || 'Todos',
    inactiveOnly:!!route.inactiveOnly,stockFilter:!!route.stockFilter,zeroOnly:!!route.zeroOnly,noTargetOnly:!!route.noTargetOnly,productId:route.productId,saleId:route.saleId,receiptId:route.receiptId,supplierListId:route.supplierListId,supplierRowId:route.supplierRowId,orderId:route.orderId,supplyTab:route.supplyTab||'orders',salesSearch:route.salesSearch || '', availableOnly:!!route.availableOnly,salesMethod:route.salesMethod||'all',pendingOnly:!!route.pendingOnly,dateFrom:route.dateFrom||'',dateTo:route.dateTo||''});
  if(state.page==='orderBuild'||state.page==='orderProducts')refreshOrderReferences();
