  Object.assign(state, {...emptyData(),saleOperationId:null,activeOperationId:null,shortageAccepted:{},completedNumber:null,demo:true,supplierLists:[],supplierAliases:[],priceReviews:[],supplierDraft:null,supplierListId:null,supplierEdit:null,purchaseOrders:[],orderDraft:null,orderId:null,lots:[],receipts:[],receiptDraft:null,products:structuredClone(seeds), sales:[], cart:{}, received:'', completed:null, salesSearch:'', saleId:null, favorites:[],availableOnly:false,salesMethod:'all',pendingOnly:false,dateFrom:'',dateTo:'',ledger:[],referenceLog:[],references:{},checks:[],countDraft:{},moneyDraft:{},favoritesDraft:[],zeroOnly:false,noTargetOnly:false});
