function supplyMenuContent(){const row=(action,glyph,title,description)=>`<button class="menu-row" data-supply-command="${action}">${icon(glyph)}<span class="grow"><strong>${title}</strong><span class="meta">${description}</span></span>${icon('chevron')}</button>`;if(state.page==='orderDetail'){const o=state.purchaseOrders.find(o=>o.id===state.orderId),open=o&&['draft','pending','partial'].includes(orderProgress(state,o).status);return row('copy','copy','Copiar pedido','Para enviarlo por tu cuenta')+(open&&!o.sentAt?row('sent','check','Marcar como enviado','Solo después de mandarlo al proveedor'):'')+(open?row('close','close','Cerrar lo pendiente','Conservar las entregas registradas'):'');}return row('list','list','Lista del proveedor','Revisar precios y presentaciones')+row('paste','plus','Pegar una lista nueva','Actualizar la referencia de costos')+(state.page==='orders'?row('direct','truck','Entrega sin pedido','Registrar mercadería que ya llegó'):'');}
