function clearCartContent(armed){return `${icon(armed?'check':'trash')}<span>${armed?'Confirmar: vaciar carrito':'Vaciar carrito'}</span>${armed?'':`<small>${units()} ${units()===1?'unidad':'unidades'}</small>`}`;}
