app.addEventListener('input', e => {
  workspace.onInput(e);
  if(e.target.closest('#purchase-presentation-form')){capturePurchaseForm();document.querySelector('#purchase-conversion').innerHTML=purchaseConversion(state.purchaseDraft);}
  if(e.target.closest('#supplier-paste-form')){const f=new FormData(e.target.closest('form'));state.supplierDraft={supplier:String(f.get('supplier')||'El Gringo'),source:String(f.get('source')||'')};}
  if(e.target.closest('#supplier-row-form')){if(e.target.name==='final')state.supplierEdit.manualPrice=true;captureSupplierRow();}
  if(e.target.id==='supplier-link-search'){state.supplierLinkSearch=e.target.value;document.querySelector('#supplier-link-results').innerHTML=supplierLinkRows();}
  if(e.target.closest('#receive-form')){captureReceiptForm();}
  if(e.target.closest('#order-form')){captureOrderForm();updateSupplyDock();}
  if(e.target.dataset.orderQty){const i=state.orderDraft.items.find(i=>i.productId===e.target.dataset.orderQty);if(i){i.packs=e.target.value;i.qty=Number(i.packs)*Number(i.unitsPerPack||0);captureOrderForm();const node=document.querySelector(`[data-order-summary="${i.productId}"]`);if(node){if(node.tagName==='P')node.innerHTML=i.qty+' unidades<span>'+(i.packCost?money(i.packs*i.packCost):'Sin costo estimado')+'</span>';else node.textContent=i.qty+' un. · '+(i.packCost?money(i.packs*i.packCost):'Sin costo');}}updateSupplyDock();}
  if(e.target.id==='order-search'){state.orderDraft.search=e.target.value;document.querySelector('#order-products').innerHTML=orderProductRows();}
  if(e.target.id==='receive-search'){state.receiptDraft.search=e.target.value;document.querySelector('#receive-products').innerHTML=receiptProductChoices();}
  if(e.target.closest('#money-form')){state.moneyDraft=Object.fromEntries(new FormData(e.target.closest('form')));refreshMovementPreview();}
  if(e.target.dataset.denomination){const value=e.target.value;if(!/^\d{0,5}$/.test(value)){e.target.value=state.countDraft.bills[e.target.dataset.denomination]||'';return;}state.countDraft.bills[e.target.dataset.denomination]=value;updateCount();}
  if(e.target.id==='count-amount'){state.countDraft.amount=e.target.value;updateCount();}
  if(e.target.closest('#new-product-form')){captureProductForm();updateNewProductPreview();}
  if(e.target.id==='cash-share'){state.cashShare=e.target.value.replace(/\D/g,'').slice(0,9);e.target.value=state.cashShare;state.transferVerified=false;document.querySelector('#mixed-error').textContent=mixedError();document.querySelector('.transfer-widget').innerHTML=transferWidget();updatePayment({format:false});}
  if(e.target.id==='customer'){state.customer=e.target.value;document.querySelector('[data-action="confirm"]').disabled=!validPayment();}
  if(e.target.id==='discount-input'){state.discountDraft=e.target.value.replace(/\D/g,'').slice(0,9);e.target.value=state.discountDraft;const value=Number(state.discountDraft||0),invalid=value>total();document.querySelector('#discount-preview').textContent=money(Math.max(0,total()-value));document.querySelector('#discount-error').textContent=invalid?'El descuento no puede superar el total.':'';e.target.setAttribute('aria-invalid',String(invalid));document.querySelector('[data-action="apply-discount"]').disabled=invalid;}

  if(e.target.id==='sales-method'){state.salesMethod=e.target.value;document.querySelector('#sales-list').innerHTML=salesList();}
  if(e.target.id==='date-from'||e.target.id==='date-to'){state[e.target.id==='date-from'?'dateFrom':'dateTo']=e.target.value;document.querySelector('#sales-list').innerHTML=salesList();}
  if(e.target.id==='sales-search'){state.salesSearch=e.target.value;document.querySelector('#sales-list').innerHTML=salesList();}
  if (e.target.id==='search') {state.search=e.target.value;document.querySelector('#product-list').innerHTML=productList(state.page==='sale');if(state.page==='sale')document.querySelector('#favorite-area').innerHTML=favoritesSection();}
  if (e.target.id==='received') {
    const input=e.target,raw=input.value.replace(/\D/g,'').slice(0,9);
    state.received=raw;updatePayment({format:false});
  }
});
